170	export function timeAgo(d: Date): string {
171	  const s = Math.floor((Date.now() - d.getTime()) / 1000);
172	  if (s < 60) return `${s}s ago`;
173	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
174	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
175	  return `${Math.floor(s / 86400)}d ago`;
176	}
