6	/** Refreshes the page every `intervalMs` while mounted (used during transitional states). */
7	export function AutoRefresh({ intervalMs = 5000 }: { intervalMs?: number }) {
8	  const router = useRouter();
9	  useEffect(() => {
10	    const t = setInterval(() => router.refresh(), intervalMs);
11	    return () => clearInterval(t);
12	  }, [router, intervalMs]);
13	  return null;
14	}
