6	export function ServerControls({
7	  serverId,
8	  status,
9	  busy,
10	}: {
11	  serverId: string;
12	  status: string;
13	  busy: boolean;
14	}) {
15	  const [pending, startTransition] = useTransition();
16	  const disabled = pending || busy;
17	
18	  const run = (action: string, confirmMsg?: string) => {
19	    if (confirmMsg && !window.confirm(confirmMsg)) return;
20	    startTransition(() => serverAction(serverId, action));
21	  };
22	
23	  return (
24	    <div className="flex flex-wrap gap-2">
25	      {status !== "RUNNING" && (
26	        <button className="btn-primary" disabled={disabled} onClick={() => run("start")}>
27	          Start
28	        </button>
29	      )}
30	      {status === "RUNNING" && (
31	        <>
32	          <button className="btn-secondary" disabled={disabled} onClick={() => run("reboot")}>
33	            Reboot
34	          </button>
35	          <button className="btn-secondary" disabled={disabled} onClick={() => run("stop")}>
36	            Stop
37	          </button>
38	        </>
39	      )}
40	      <button
41	        className="btn-secondary"
42	        disabled={disabled}
43	        onClick={() =>
44	          run("reinstall", "Reinstall wipes ALL data on this VPS and redeploys the OS. Continue?")
45	        }
46	      >
47	        Reinstall
48	      </button>
49	      <button
50	        className="btn-danger"
51	        disabled={disabled}
52	        onClick={() =>
53	          run("delete", "Permanently delete this VPS and all its data? This cannot be undone.")
54	        }
55	      >
56	        Delete
57	      </button>
58	    </div>
