43	        </div>
44	        <div className="flex items-center justify-between">
45	          <dt className="text-slate-400">Auto-renew</dt>
46	          <dd>
47	            <button
48	              className={autoRenew ? "btn-secondary py-1" : "btn-primary py-1"}
49	              disabled={pending}
50	              onClick={() => start(() => toggleAutoRenew(serverId))}
51	            >
52	              {autoRenew ? "On — turn off" : "Off — turn on"}
53	            </button>
54	          </dd>
55	        </div>
56	      </dl>
57	      <button
58	        className="btn-primary mt-4 w-full"
59	        disabled={pending}
60	        onClick={() =>
