140	export async function serverAction(serverId: string, action: string) {
141	  const { user, server } = await ownedServer(serverId);
142	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
143	    start: "START",
144	    stop: "STOP",
145	    reboot: "REBOOT",
146	    reinstall: "REINSTALL",
147	    delete: "DELETE",
148	  };
149	  const type = allowed[action];
150	  if (!type) throw new Error("Invalid action");
151	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
152	    throw new Error("Server is suspended");
153	  }
154	
155	  const pending = await db.job.count({
156	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
157	  });
158	  if (pending > 0) return; // debounce: one job at a time per server
159	
160	  if (type === "DELETE") {
161	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
162	  }
163	  await db.job.create({ data: { type, serverId } });
164	  await audit(user.id, `server.${action}`, serverId);
165	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
166	  revalidatePath(`/dashboard/servers/${serverId}`);
167	}
