202	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
203	  const { user, server } = await ownedServer(serverId);
204	  if (server.isFree || !server.expiresAt) return;
205	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
206	  if (!plan) return;
207	  const owner = await db.user.findUnique({ where: { id: server.userId } });
208	  if (!owner || owner.balanceCents < plan.priceCents) {
209	    return { error: "Insufficient balance — top up your wallet first." };
210	  }
211	
212	  const base = Math.max(server.expiresAt.getTime(), Date.now());
213	  await db.$transaction([
214	    db.user.update({
215	      where: { id: server.userId },
216	      data: { balanceCents: { decrement: plan.priceCents } },
217	    }),
218	    db.walletTransaction.create({
219	      data: {
220	        userId: server.userId,
221	        amountCents: -plan.priceCents,
222	        description: `Renewal: ${plan.name} VPS (${server.hostname})`,
223	      },
224	    }),
225	    db.server.update({
226	      where: { id: serverId },
227	      data: { expiresAt: new Date(base + 30 * 86400_000), suspendedNote: null },
228	    }),
229	  ]);
230	  await audit(user.id, "server.renew_now", serverId);
231	
232	  // Unpaid-suspended server springs back to life once paid
233	  if (server.status === "SUSPENDED") {
234	    const pending = await db.job.count({
235	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
236	    });
237	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
238	  }
239	  revalidatePath(`/dashboard/servers/${serverId}`);
240	}
