16	async function queueJob(
17	  serverId: string,
18	  type: "SNAPSHOT_CREATE" | "SNAPSHOT_DELETE" | "SNAPSHOT_ROLLBACK" | "BACKUP_CREATE" | "RESIZE",
19	  payload?: Record<string, unknown>
