104	const PF_MIN = 20000;
105	const PF_MAX = 29999;
106	const MAX_FORWARDS_PER_SERVER = 10;
107	
108	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
109	  const serverId = String(formData.get("serverId") ?? "");
110	  const { user, server } = await ownedServer(serverId);
111	  const parsed = z
112	    .object({
113	      guestPort: z.coerce.number().int().min(1).max(65535),
114	      protocol: z.enum(["tcp", "udp"]),
115	    })
116	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
117	  if (!parsed.success) return { error: "Invalid port." };
118	
119	  const count = await db.portForward.count({ where: { serverId } });
120	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
121	
122	  const used = new Set([
123	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
124	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
125	  ]);
126	  let publicPort = 0;
127	  for (let p = PF_MIN; p <= PF_MAX; p++) {
128	    if (!used.has(p)) { publicPort = p; break; }
129	  }
130	  if (!publicPort) return { error: "No public ports available." };
131	
132	  await db.portForward.create({
133	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
134	  });
135	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
136	  await db.auditLog.create({
137	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
138	  });
139	  revalidatePath(`/dashboard/servers/${serverId}`);
140	  return {};
141	}
