40	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
41	
42	  const contactParsed = contactSchema.safeParse({
43	    firstName: formData.get("firstName"),
44	    lastName: formData.get("lastName"),
45	    address1: formData.get("address1"),
