52	  });
53	  if (!contactParsed.success) {
54	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
55	  }
56	
57	  const priceCents = priceForDomain(domain);
58	  if (priceCents === null) return { error: "This TLD is not supported yet." };
59	  if (user.balanceCents < priceCents) {
60	    return { error: `Insufficient balance — this domain costs $${(priceCents / 100).toFixed(2)}/yr.` };
61	  }
62	
63	  const existing = await db.domain.findUnique({ where: { name: domain } });
64	  if (existing) return { error: "This domain is already managed by another account." };
65	
66	  const [check] = await checkDomains([domain]);
67	  if (!check?.available) return { error: "Domain is not available." };
68	  if (check.premium) return { error: "Premium domains are not supported yet." };
69	
70	  // Charge first, refund on failure
71	  const record = await db.$transaction(async (tx) => {
72	    await tx.user.update({ where: { id: user.id }, data: { balanceCents: { decrement: priceCents } } });
73	    await tx.walletTransaction.create({
