97	        data: { userId: user.id, amountCents: priceCents, description: `Refund: failed registration ${domain}` },
98	      }),
99	      db.domain.update({
100	        where: { id: record.id },
101	        data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 500) },
102	      }),
103	    ]);
104	    return { error: `Registration failed: ${String(e?.message ?? e).slice(0, 200)} (you were refunded).` };
