56	export async function waitForTask(upid: string, timeoutMs = 300_000): Promise<void> {
57	  const start = Date.now();
58	  while (Date.now() - start < timeoutMs) {
59	    const status = await pve.get(`/nodes/${NODE}/tasks/${encodeURIComponent(upid)}/status`);
60	    if (status.status === "stopped") {
61	      if (status.exitstatus !== "OK") {
62	        throw new Error(`Proxmox task failed: ${status.exitstatus}`);
63	      }
64	      return;
65	    }
66	    await new Promise((r) => setTimeout(r, 2000));
67	  }
68	  throw new Error(`Proxmox task timed out: ${upid}`);
69	}
