1	import { XMLParser } from "fast-xml-parser";
2	
3	const parser = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: "@_" });
4	
5	export function namecheapConfigured(): boolean {
6	  return !!(process.env.NAMECHEAP_API_USER && process.env.NAMECHEAP_API_KEY);
7	}
8	
9	function baseUrl(): string {
10	  return process.env.NAMECHEAP_SANDBOX === "1"
11	    ? "https://api.sandbox.namecheap.com/xml.response"
12	    : "https://api.namecheap.com/xml.response";
13	}
14	
15	async function ncRequest(command: string, params: Record<string, string> = {}): Promise<any> {
16	  if (!namecheapConfigured()) throw new Error("Namecheap API is not configured");
17	  const url = new URL(baseUrl());
18	  url.searchParams.set("ApiUser", process.env.NAMECHEAP_API_USER!);
19	  url.searchParams.set("ApiKey", process.env.NAMECHEAP_API_KEY!);
20	  url.searchParams.set("UserName", process.env.NAMECHEAP_USERNAME ?? process.env.NAMECHEAP_API_USER!);
21	  url.searchParams.set("ClientIp", process.env.NAMECHEAP_CLIENT_IP ?? "127.0.0.1");
22	  url.searchParams.set("Command", command);
23	  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
24	
25	  const res = await fetch(url, { signal: AbortSignal.timeout(30_000) });
26	  const xml = await res.text();
27	  const doc = parser.parse(xml);
28	  const api = doc.ApiResponse;
29	  if (!api) throw new Error("Namecheap: malformed response");
30	  if (api["@_Status"] !== "OK") {
31	    const errs = api.Errors?.Error;
32	    const msg = Array.isArray(errs)
33	      ? errs.map((e: any) => e["#text"] ?? e).join("; ")
34	      : errs?.["#text"] ?? errs ?? "unknown error";
35	    throw new Error(`Namecheap: ${msg}`);
36	  }
37	  return api.CommandResponse;
38	}
