1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { checkDomains, namecheapConfigured, priceForDomain, TLD_PRICES } from "@/lib/namecheap";
4	
5	export async function GET(req: NextRequest) {
6	  const user = await currentUser();
7	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
8	
9	  const q = (req.nextUrl.searchParams.get("q") ?? "").toLowerCase().trim().replace(/[^a-z0-9.-]/g, "");
10	  if (q.length < 2) return NextResponse.json({ results: [] });
11	  if (!namecheapConfigured()) {
12	    return NextResponse.json({ configured: false, results: [] });
13	  }
14	
15	  const base = q.includes(".") ? q.slice(0, q.indexOf(".")) : q;
16	  const candidates = q.includes(".")
17	    ? [q, ...["com", "net", "io", "dev"].filter((t) => q !== `${base}.${t}`).map((t) => `${base}.${t}`)]
18	    : ["com", "net", "io", "dev", "app", "xyz"].map((t) => `${base}.${t}`);
19	
20	  try {
21	    const checks = await checkDomains(candidates.slice(0, 8));
22	    return NextResponse.json({
23	      configured: true,
24	      results: checks
25	        .map((c) => ({ ...c, priceCents: priceForDomain(c.domain) }))
26	        .filter((c) => c.priceCents !== null),
27	    });
28	  } catch (e: any) {
29	    return NextResponse.json({ configured: true, error: String(e?.message ?? e).slice(0, 200), results: [] });
30	  }
31	}
32	
33	export async function OPTIONS() {
34	  return NextResponse.json({ tlds: TLD_PRICES });
35	}
