/** Shared helpers for presenting audit-log actions. Pure — safe in server and client components. */

const SCOPE_LABELS: Record<string, string> = {
  user: "Account",
  server: "Server",
  wallet: "Wallet",
  domain: "Domain",
  admin: "Admin",
};

export function humanizeAction(action: string): string {
  const dot = action.indexOf(".");
  if (dot === -1) return action.replace(/_/g, " ");
  const scope = action.slice(0, dot);
  const verb = action.slice(dot + 1).replace(/_/g, " ");
  return `${SCOPE_LABELS[scope] ?? scope[0]?.toUpperCase() + scope.slice(1)} · ${verb}`;
}

export function actionDotColor(action: string): string {
  if (action.includes("delete") || action.includes("suspend")) return "bg-red-400";
  if (action.startsWith("wallet") || action.includes("renew") || action.includes("topup")) return "bg-emerald-400";
  if (action.startsWith("domain")) return "bg-accent-cyan";
  if (action.startsWith("admin")) return "bg-amber-400";
  return "bg-brand-400";
}

"use client";

import { useState, type ReactNode } from "react";

const TABS = [
  "Overview",
  "Metrics",
  "Snapshots",
  "Backups",
  "Networking",
  "Resize",
  "Activity",
] as const;

export function ServerTabs({
  initialTab,
  overview,
  metrics,
  snapshots,
  backups,
  networking,
  resize,
  activity,
}: {
  initialTab?: string;
  overview: ReactNode;
  metrics: ReactNode;
  snapshots: ReactNode;
  backups: ReactNode;
  networking: ReactNode;
  resize: ReactNode;
  activity: ReactNode;
}) {
  const keys = TABS.map((t) => t.toLowerCase());
  const [tab, setTab] = useState<string>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
  );

  const panels: Record<string, ReactNode> = {
    overview,
    metrics,
    snapshots,
    backups,
    networking,
    resize,
    activity,
  };

  return (
    <div>
      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
        {TABS.map((t) => {
          const k = t.toLowerCase();
          const active = tab === k;
          return (
            <button
              key={k}
              type="button"
              onClick={() => {
                setTab(k);
                window.history.replaceState(null, "", `?tab=${k}`);
              }}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {t}
            </button>
          );
        })}
      </div>
      <div className="animate-fade-up">{panels[tab]}</div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { AreaChart } from "@/components/ui/charts";

type Row = {
  time: number;
  cpu: number | null;
  mem: number | null;
  maxmem: number | null;
  netin: number | null;
  netout: number | null;
};

const TIMEFRAMES = [
  { key: "hour", label: "1h" },
  { key: "day", label: "24h" },
  { key: "week", label: "7d" },
  { key: "month", label: "30d" },
] as const;

function xLabelsFor(rows: Row[], tf: string): string[] {
  if (rows.length < 2) return [];
  const n = 6;
  const labels: string[] = [];
  for (let i = 0; i < n; i++) {
    const idx = Math.round((i / (n - 1)) * (rows.length - 1));
    const d = new Date(rows[idx].time * 1000);
    labels.push(
      tf === "hour" || tf === "day"
        ? `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`
        : `${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`
    );
  }
  return labels;
}

export function MetricsPanel({ serverId }: { serverId: string }) {
  const [tf, setTf] = useState<string>("hour");
  const [rows, setRows] = useState<Row[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (timeframe: string, quiet: boolean) => {
    if (!quiet) setRows(null);
    setError(null);
    try {
      const res = await fetch(`/api/metrics?serverId=${serverId}&tf=${timeframe}`, {
        cache: "no-store",
      });
      if (!res.ok) throw new Error("metrics unavailable");
      const json: { data?: Row[] } = await res.json();
      setRows(
        (json.data ?? []).filter(
          (r) => r && typeof r.time === "number" && (r.cpu !== null || r.mem !== null)
        )
      );
    } catch {
      setError("Metrics are temporarily unavailable — the hypervisor may be busy.");
      setRows([]);
    }
  }, [serverId]);

  useEffect(() => {
    void load(tf, false);
    const t = setInterval(() => void load(tf, true), 30_000);
    return () => clearInterval(t);
  }, [tf, load]);

  const loading = rows === null;
  const data = rows ?? [];
  const xLabels = xLabelsFor(data, tf);
  const maxMemGB = Math.max(...data.map((r) => (r.maxmem ?? 0) / 1e9), 1);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <p className="section-label">Resource usage</p>
        <div className="flex gap-1 rounded-xl border border-white/[0.08] bg-white/[0.03] p-1">
          {TIMEFRAMES.map((t) => (
            <button
              key={t.key}
              type="button"
              onClick={() => setTf(t.key)}
              className={`rounded-lg px-3 py-1 text-xs font-semibold transition-colors ${
                tf === t.key
                  ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white"
                  : "text-slate-400 hover:text-white"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      {error && (
        <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
          {error}
        </div>
      )}

      {loading ? (
        <div className="space-y-6">
          <div className="skeleton h-56 w-full" />
          <div className="skeleton h-56 w-full" />
          <div className="skeleton h-56 w-full" />
        </div>
      ) : data.length === 0 ? (
        !error && (
          <div className="card py-10 text-center text-sm text-slate-400">
            No metric samples yet — data appears a few minutes after the server first boots.
          </div>
        )
      ) : (
        <>
          <div className="card">
            <h3 className="mb-4 text-sm font-semibold">CPU usage</h3>
            <AreaChart
              id={`cpu-${tf}`}
              series={[{ name: "CPU", data: data.map((r) => (r.cpu ?? 0) * 100), color: "#8a70fb" }]}
              maxY={100}
              yLabel={(v) => `${v.toFixed(0)}%`}
              xLabels={xLabels}
            />
          </div>
          <div className="card">
            <h3 className="mb-4 text-sm font-semibold">Memory</h3>
            <AreaChart
              id={`mem-${tf}`}
              series={[{ name: "Memory", data: data.map((r) => (r.mem ?? 0) / 1e9), color: "#3b82f6" }]}
              maxY={maxMemGB}
              yLabel={(v) => `${v.toFixed(1)} GB`}
              xLabels={xLabels}
            />
          </div>
          <div className="card">
            <div className="mb-4 flex items-center gap-4">
              <h3 className="text-sm font-semibold">Network</h3>
              <span className="flex items-center gap-1.5 text-xs text-slate-400">
                <span className="h-2 w-2 rounded-full bg-[#22d3ee]" /> in
              </span>
              <span className="flex items-center gap-1.5 text-xs text-slate-400">
                <span className="h-2 w-2 rounded-full bg-[#8a70fb]" /> out
              </span>
            </div>
            <AreaChart
              id={`net-${tf}`}
              series={[
                { name: "In", data: data.map((r) => (r.netin ?? 0) / 1024), color: "#22d3ee" },
                { name: "Out", data: data.map((r) => (r.netout ?? 0) / 1024), color: "#8a70fb" },
              ]}
              yLabel={(v) => `${v.toFixed(0)} KB/s`}
              xLabels={xLabels}
            />
          </div>
        </>
      )}
      <p className="text-xs text-slate-500">Charts refresh automatically every 30 seconds.</p>
    </div>
  );
}

"use client";

import { useState } from "react";

export function CopyText({ text, label }: { text: string; label?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost px-2 py-1 text-xs"
      onClick={() => {
        void navigator.clipboard.writeText(text).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        });
      }}
    >
      {copied ? "Copied ✓" : label ?? "Copy"}
    </button>
  );
}

export function RevealPassword({ password }: { password: string }) {
  const [shown, setShown] = useState(false);
  return (
    <span className="inline-flex items-center gap-2">
      <button
        type="button"
        onClick={() => setShown((s) => !s)}
        className="cursor-pointer rounded-lg border border-white/10 bg-white/[0.04] px-2 py-0.5 font-mono text-xs hover:border-white/20"
        title={shown ? "Hide password" : "Click to reveal"}
      >
        {shown ? password : "••••••••••••"}
      </button>
      {shown && <CopyText text={password} />}
    </span>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { assignServerProject } from "@/lib/actions-account";

export function ProjectAssign({
  serverId,
  currentProjectId,
  projects,
}: {
  serverId: string;
  currentProjectId: string | null;
  projects: { id: string; name: string; color: string }[];
}) {
  const [pending, start] = useTransition();
  const [value, setValue] = useState(currentProjectId ?? "");

  if (projects.length === 0) {
    return (
      <p className="text-sm text-slate-400">
        No projects yet.{" "}
        <Link href="/dashboard/projects" className="text-brand-300 hover:underline">
          Create one
        </Link>{" "}
        to group your servers.
      </p>
    );
  }

  return (
    <div className="flex items-center gap-3">
      <select
        className="input max-w-xs"
        value={value}
        disabled={pending}
        onChange={(e) => {
          const v = e.target.value;
          setValue(v);
          start(() => assignServerProject(serverId, v === "" ? null : v));
        }}
      >
        <option value="">— No project —</option>
        {projects.map((p) => (
          <option key={p.id} value={p.id}>
            {p.name}
          </option>
        ))}
      </select>
