"use client";

import { useState, useTransition } from "react";
import { createSnapshot, deleteSnapshot, rollbackSnapshot } from "@/lib/actions-server";

export function CreateSnapshotForm({ serverId, disabled }: { serverId: string; disabled?: boolean }) {
  const [name, setName] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  return (
    <div>
      <div className="flex flex-wrap items-end gap-3">
        <div>
          <label className="label">Snapshot name</label>
          <input
            className="input w-56"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="before_upgrade"
            maxLength={40}
            disabled={pending || disabled}
          />
        </div>
        <button
          className="btn-primary"
          disabled={pending || disabled || name.trim().length < 2}
          onClick={() =>
            start(async () => {
              setError(null);
              const res = await createSnapshot(serverId, name.trim());
              if (res?.error) setError(res.error);
              else setName("");
            })
          }
        >
          {pending ? "Creating…" : "Create snapshot"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      <p className="mt-2 text-xs text-slate-500">Letters, digits and underscores only.</p>
    </div>
  );
}

export function SnapshotActions({
  serverId,
  name,
  disabled,
}: {
  serverId: string;
  name: string;
  disabled?: boolean;
}) {
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const run = (fn: () => Promise<{ error?: string }>, confirmMsg: string) => {
    if (!window.confirm(confirmMsg)) return;
    start(async () => {
      setError(null);
      const res = await fn();
      if (res?.error) setError(res.error);
    });
  };

  return (
    <div className="flex items-center justify-end gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        className="btn-secondary px-3 py-1 text-xs"
        disabled={pending || disabled}
        onClick={() =>
          run(
            () => rollbackSnapshot(serverId, name),
            `Roll back to snapshot "${name}"? All changes made after this snapshot will be lost.`
          )
        }
      >
        Rollback
      </button>
      <button
        className="btn-danger px-3 py-1 text-xs"
        disabled={pending || disabled}
        onClick={() =>
          run(
            () => deleteSnapshot(serverId, name),
            `Delete snapshot "${name}"? This cannot be undone.`
          )
        }
      >
        Delete
      </button>
    </div>
  );
}

