"use client";

import { useState, useTransition } from "react";
import { resizeServer } from "@/lib/actions-server";
import { fmtMoney } from "@/components/ui/primitives";

type PlanRow = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
};

export function ResizePicker({
  serverId,
  currentPlanId,
  currentDiskGB,
  plans,
  disabled,
}: {
  serverId: string;
  currentPlanId: string;
  currentDiskGB: number;
  plans: PlanRow[];
  disabled?: boolean;
}) {
  const [selected, setSelected] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const target = plans.find((p) => p.id === selected);

  return (
    <div className="space-y-5">
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {plans.map((p) => {
          const current = p.id === currentPlanId;
          const tooSmall = p.diskGB < currentDiskGB;
          const active = selected === p.id;
          return (
            <button
              key={p.id}
              type="button"
              disabled={current || tooSmall || pending || disabled}
              title={
                tooSmall
                  ? `Disk can only grow — this plan has ${p.diskGB} GB, your server uses a ${currentDiskGB} GB disk.`
                  : undefined
              }
              onClick={() => setSelected(active ? null : p.id)}
              className={`card p-4 text-left transition-all ${
                current
                  ? "border-brand-400/60 ring-1 ring-brand-400/60"
                  : tooSmall
                    ? "cursor-not-allowed opacity-40"
                    : active
                      ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue"
                      : "cursor-pointer hover:border-white/20"
              }`}
            >
              <div className="flex items-baseline justify-between">
                <span className="font-semibold">{p.name}</span>
                <span className="text-lg font-bold">{fmtMoney(p.priceCents)}<span className="text-xs font-normal text-slate-400">/mo</span></span>
              </div>
              <p className="mt-1 text-sm text-slate-400">
                {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM · {p.diskGB} GB NVMe · {p.bandwidthTB} TB
              </p>
              {current && <p className="mt-2 text-xs font-semibold text-brand-300">Current plan</p>}
              {tooSmall && <p className="mt-2 text-xs text-slate-500">Smaller disk — unavailable</p>}
            </button>
          );
        })}
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
        <p className="text-xs text-slate-400">
          Resizing requires a power cycle. The new price applies at your next renewal.
        </p>
        <button
          className="btn-primary"
          disabled={!target || pending || disabled}
          onClick={() => {
            if (!target) return;
            if (
              !window.confirm(
                `Resize this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)? The server will be power-cycled.`
              )
            )
              return;
            start(async () => {
              setError(null);
              const res = await resizeServer(serverId, target.id);
              if (res?.error) setError(res.error);
              else setSelected(null);
            });
          }}
        >
          {pending ? "Resizing…" : target ? `Resize to ${target.name}` : "Select a plan"}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { StatusDot, Badge, EmptyState } from "@/components/ui/primitives";

export type ServerRow = {
  id: string;
  hostname: string;
  status: string;
  isFree: boolean;
  planLine: string;
  osName: string;
  project: { name: string; color: string } | null;
  endpoint: string | null;
  created: string;
};

export function ServersList({ servers }: { servers: ServerRow[] }) {
  const [filter, setFilter] = useState<string>("ALL");

  const statuses = useMemo(() => {
    const set = new Map<string, number>();
    for (const s of servers) set.set(s.status, (set.get(s.status) ?? 0) + 1);
    return Array.from(set.entries());
  }, [servers]);

  const visible = filter === "ALL" ? servers : servers.filter((s) => s.status === filter);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          onClick={() => setFilter("ALL")}
          className={`rounded-full border px-3.5 py-1.5 text-xs font-medium transition-colors ${
            filter === "ALL"
              ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
              : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-white"
          }`}
        >
          All · {servers.length}
        </button>
        {statuses.map(([status, count]) => (
          <button
            key={status}
            type="button"
            onClick={() => setFilter(filter === status ? "ALL" : status)}
            className={`rounded-full border px-3.5 py-1.5 text-xs font-medium transition-colors ${
              filter === status
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-white"
            }`}
          >
            {status.toLowerCase().replace(/_/g, " ")} · {count}
          </button>
        ))}
      </div>

      {visible.length === 0 ? (
        <EmptyState
          title="Nothing matches this filter"
          sub="No servers are currently in this state."
          action={
            <button className="btn-secondary" onClick={() => setFilter("ALL")}>
              Show all servers
            </button>
          }
        />
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="table-shell min-w-[760px]">
            <thead>
              <tr>
                <th>Status</th>
                <th>Hostname</th>
                <th>Project</th>
                <th>Specs</th>
                <th>Access</th>
                <th>Created</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {visible.map((s) => (
                <tr key={s.id}>
                  <td>
                    <StatusDot status={s.status} />
                  </td>
                  <td>
                    <Link
                      href={`/dashboard/servers/${s.id}`}
                      className="font-semibold text-slate-100 hover:text-brand-300"
                    >
                      {s.hostname}
                    </Link>
                    {s.isFree && (
                      <span className="ml-2 align-middle">
                        <Badge tone="brand">free</Badge>
                      </span>
                    )}
                    <p className="text-xs text-slate-500">{s.osName}</p>
                  </td>
                  <td>
                    {s.project ? (
                      <span className="inline-flex items-center gap-2 text-xs text-slate-300">
                        <span
                          className="h-2.5 w-2.5 rounded-full"
                          style={{ background: s.project.color }}
                        />
                        {s.project.name}
                      </span>
                    ) : (
                      <span className="text-xs text-slate-600">—</span>
                    )}
                  </td>
                  <td className="text-slate-400">{s.planLine}</td>
                  <td className="font-mono text-xs text-slate-400">{s.endpoint ?? "—"}</td>
                  <td className="text-slate-400">{s.created}</td>
                  <td className="text-right">
                    <Link href={`/dashboard/servers/${s.id}`} className="btn-secondary px-3 py-1 text-xs">
                      Manage
