"use client";

import { useActionState, useState } from "react";
import Link from "next/link";
import { orderServer } from "@/lib/actions";
import { fmtMoney } from "@/components/ui/primitives";

type PlanRow = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
};
type OsRow = { id: string; slug: string; name: string };

const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/;
const STEPS = ["Configure", "Details", "Review"] as const;

function osColor(slug: string): string {
  const s = slug.toLowerCase();
  if (s.includes("ubuntu")) return "#E95420";
  if (s.includes("debian")) return "#A81D33";
  if (s.includes("rocky") || s.includes("alma") || s.includes("centos")) return "#10B981";
  if (s.includes("fedora")) return "#3B82F6";
  return "#8a70fb";
}

export function DeployWizard({
  plans,
  osTemplates,
  isAdmin,
  balanceCents,
  sshKeyCount,
}: {
  plans: PlanRow[];
  osTemplates: OsRow[];
  isAdmin: boolean;
  balanceCents: number;
  sshKeyCount: number;
}) {
  const [state, action, pending] = useActionState(orderServer, {});
  const [step, setStep] = useState(0);
  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
  const [osId, setOsId] = useState(osTemplates[0]?.id ?? "");
  const [hostname, setHostname] = useState("");
  const [free, setFree] = useState(false);

  const plan = plans.find((p) => p.id === planId);
  const os = osTemplates.find((o) => o.id === osId);
  const recommendedIdx = plans.length >= 3 ? Math.floor((plans.length - 1) / 2) : -1;
  const hostnameValid = hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname);
  const dueCents = free ? 0 : plan?.priceCents ?? 0;
  const afterCents = balanceCents - dueCents;
  const canNext = step === 0 ? Boolean(planId && osId) : step === 1 ? hostnameValid : true;

  return (
    <form action={action} className="space-y-6">
      {/* Progress */}
      <div className="flex items-center gap-3">
        {STEPS.map((label, i) => (
          <div key={label} className="flex items-center gap-3">
            <div className="flex items-center gap-2">
              <span
                className={`flex h-7 w-7 items-center justify-center rounded-full text-xs font-bold transition-colors ${
                  i < step
                    ? "bg-emerald-500/20 text-emerald-300"
                    : i === step
                      ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white"
                      : "border border-white/10 text-slate-500"
                }`}
              >
                {i < step ? "✓" : i + 1}
              </span>
              <span
                className={`text-sm font-medium ${i === step ? "text-white" : "text-slate-500"}`}
              >
                {label}
              </span>
            </div>
            {i < STEPS.length - 1 && <div className="h-px w-8 bg-white/10 sm:w-14" />}
          </div>
        ))}
      </div>

      {state?.error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {state.error}
        </div>
      )}

      {/* Step 1 — OS + plan */}
      <div className={step === 0 ? "space-y-6" : "hidden"}>
        <div>
          <p className="section-label mb-3">Operating system</p>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {osTemplates.map((o) => {
              const color = osColor(o.slug);
              const active = osId === o.id;
              return (
                <button
                  type="button"
                  key={o.id}
                  onClick={() => setOsId(o.id)}
                  className={`card flex cursor-pointer items-center gap-3 p-4 text-left transition-all ${
                    active ? "border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
                  }`}
                >
                  <span
                    className="flex h-10 w-10 items-center justify-center rounded-xl text-sm font-bold"
                    style={{ background: `${color}22`, color }}
                  >
                    {o.name.slice(0, 2)}
                  </span>
                  <span className="font-medium">{o.name}</span>
                </button>
              );
            })}
          </div>
        </div>

        <div>
          <p className="section-label mb-3">Plan</p>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {plans.map((p, i) => {
              const active = planId === p.id;
              return (
                <button
                  type="button"
                  key={p.id}
                  onClick={() => setPlanId(p.id)}
                  className={`card relative cursor-pointer p-4 text-left transition-all ${
                    active ? "border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
                  }`}
                >
                  {i === recommendedIdx && (
                    <span className="absolute -top-2.5 right-4 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-white">
                      Recommended
                    </span>
                  )}
                  <div className="flex items-baseline justify-between">
                    <span className="font-semibold">{p.name}</span>
                    <span className="text-lg font-bold">
                      {fmtMoney(p.priceCents)}
                      <span className="text-xs font-normal text-slate-400">/mo</span>
                    </span>
                  </div>
                  <ul className="mt-2 space-y-1 text-sm text-slate-400">
                    <li>{p.cpuCores} vCPU</li>
                    <li>{p.ramMB / 1024} GB RAM</li>
                    <li>{p.diskGB} GB NVMe SSD</li>
                    <li>{p.bandwidthTB} TB bandwidth</li>
                  </ul>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Step 2 — details */}
      <div className={step === 1 ? "space-y-6" : "hidden"}>
        <div className="card max-w-lg">
          <label className="label" htmlFor="wizard-hostname">
            Hostname
          </label>
          <input
            id="wizard-hostname"
            className="input"
            value={hostname}
            onChange={(e) => setHostname(e.target.value.toLowerCase())}
            placeholder="web-01"
            maxLength={40}
            autoComplete="off"
          />
          {hostname.length > 0 && !hostnameValid ? (
            <p className="mt-2 text-xs text-red-400">
              3–40 characters: lowercase letters, digits and hyphens; must start and end with a
              letter or digit.
            </p>
          ) : (
            <p className="mt-2 text-xs text-slate-500">
              Used as the server name and system hostname.
            </p>
          )}
        </div>

        <div className="glass flex items-start gap-3 p-4">
          <span className="mt-0.5 text-brand-300">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
              <rect x="3" y="11" width="18" height="10" rx="2" />
              <path d="M7 11V7a5 5 0 0 1 10 0v4" />
            </svg>
          </span>
          <div className="text-sm text-slate-300">
            <p className="font-medium">SSH keys are injected automatically</p>
            <p className="mt-0.5 text-slate-400">
              {sshKeyCount > 0
                ? `Your ${sshKeyCount} saved SSH ${sshKeyCount === 1 ? "key" : "keys"} will be added to the new server's root account.`
                : "You have no SSH keys saved yet — you can still log in with the generated root password."}{" "}
              <Link href="/dashboard/settings" className="text-brand-300 hover:underline">
                Manage keys in Settings
              </Link>
              .
            </p>
          </div>
        </div>
      </div>

      {/* Step 3 — review */}
      <div className={step === 2 ? "space-y-6" : "hidden"}>
        <div className="card max-w-xl">
          <h3 className="mb-4 font-semibold">Order summary</h3>
          <dl className="space-y-3 text-sm">
            <div className="flex justify-between">
              <dt className="text-slate-400">Server</dt>
              <dd className="font-mono">{hostname || "—"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Operating system</dt>
              <dd>{os?.name ?? "—"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Plan</dt>
              <dd>
                {plan
                  ? `${plan.name} — ${plan.cpuCores} vCPU / ${plan.ramMB / 1024} GB / ${plan.diskGB} GB`
                  : "—"}
              </dd>
            </div>
            <div className="divider" />
            <div className="flex justify-between">
              <dt className="text-slate-400">Monthly price</dt>
              <dd>{plan ? `${fmtMoney(free ? 0 : plan.priceCents)}/mo` : "—"}</dd>
            </div>
            <div className="flex justify-between text-base font-semibold">
              <dt>Due today</dt>
              <dd>{fmtMoney(dueCents)}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Wallet balance after</dt>
              <dd className={afterCents < 0 ? "font-semibold text-red-400" : "text-emerald-400"}>
                {fmtMoney(afterCents)}
              </dd>
            </div>
          </dl>

          {isAdmin && (
            <label className="mt-4 flex cursor-pointer items-center gap-2 rounded-xl border border-brand-500/30 bg-brand-500/10 px-4 py-3 text-sm text-brand-200">
              <input
                type="checkbox"
                name="free"
                value="1"
                checked={free}
                onChange={(e) => setFree(e.target.checked)}
              />
              Free deployment (admin) — no billing, never expires
            </label>
          )}

          {!free && afterCents < 0 && (
            <div className="mt-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
              Insufficient balance.{" "}
              <Link href="/dashboard/billing" className="font-semibold underline">
                Add funds
              </Link>{" "}
              to complete this order.
            </div>
          )}
        </div>
      </div>

      {/* Carried values */}
      <input type="hidden" name="planId" value={planId} />
      <input type="hidden" name="osTemplateId" value={osId} />
      <input type="hidden" name="hostname" value={hostname} />

      {/* Nav */}
      <div className="flex items-center justify-between">
        <button
          type="button"
          className="btn-secondary"
          onClick={() => setStep((s) => Math.max(0, s - 1))}
          disabled={step === 0 || pending}
        >
          ← Back
        </button>
        {step < 2 ? (
          <button
            type="button"
            className="btn-primary px-6"
            disabled={!canNext}
            onClick={() => setStep((s) => Math.min(2, s + 1))}
          >
            Continue →
          </button>
        ) : (
          <button
            type="submit"
            className="btn-primary px-8"
            disabled={pending || !plan || !os || !hostnameValid || (!free && afterCents < 0)}
          >
            {pending ? "Deploying…" : `Deploy server · ${fmtMoney(dueCents)}`}
          </button>
        )}
      </div>
    </form>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { fmtMoney } from "@/components/ui/primitives";

type Result = { domain: string; available: boolean; premium: boolean; priceCents: number };

export function DomainSearch({ configured }: { configured: boolean }) {
  const [q, setQ] = useState("");
  const [results, setResults] = useState<Result[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!configured) return;
    if (timer.current) clearTimeout(timer.current);
    const query = q.trim().toLowerCase();
    if (query.length < 2) {
      setResults(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    timer.current = setTimeout(async () => {
      try {
        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, {
          cache: "no-store",
        });
        const json: { results?: Result[]; error?: string } = await res.json();
        setError(json.error ?? null);
        setResults(json.results ?? []);
      } catch {
        setError("Search failed — try again.");
        setResults([]);
      }
      setLoading(false);
    }, 400);
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
  }, [q, configured]);

  return (
    <div className="card bg-gradient-to-br from-navy-900/90 to-navy-850/70">
      <h2 className="text-lg font-semibold">
        Find your <span className="grad-text">perfect domain</span>
      </h2>
      <p className="mt-1 text-sm text-slate-400">
        Search across .com, .net, .io, .dev and more — registered in seconds, paid from your wallet.
      </p>

      <div className="relative mt-4 max-w-xl">
        <input
