      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
    },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();

  const [projects, activePlans] = await Promise.all([
    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  ]);

  const publicIp = process.env.PUBLIC_IP ?? "";
  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
  const busy =
    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
  const steady = ["RUNNING", "STOPPED"].includes(server.status);

  let live: LiveStats = null;
  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
  let backups: { volid: string; ctime?: number; size?: number }[] = [];
  let pveUnavailable = false;

  if (server.vmid && steady) {
    const results = await Promise.allSettled([
      vmStatus(server.vmid),
      listSnapshots(server.vmid),
      listBackups(server.vmid),
    ]);
    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
    pveUnavailable = results.some((r) => r.status === "rejected");
  }

  const sshCommand = server.sshPort ? `ssh root@${publicIp} -p ${server.sshPort}` : null;

  /* ---------- Tab: Overview ---------- */
  const overview = (
    <div className="grid gap-6 md:grid-cols-2">
      <div className="card">
        <h2 className="mb-4 font-semibold">Access</h2>
        <dl className="space-y-3 text-sm">
          <div>
            <dt className="text-slate-400">SSH command</dt>
            <dd className="mt-1 flex items-center gap-2">
              <code className="rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
                {sshCommand ?? "provisioning…"}
              </code>
              {sshCommand && <CopyText text={sshCommand} />}
            </dd>
          </div>
          <div className="flex items-center justify-between">
            <dt className="text-slate-400">Root password</dt>
            <dd>
              {server.rootPassword ? (
                <RevealPassword password={server.rootPassword} />
              ) : (
                <span className="text-slate-500">—</span>
              )}
            </dd>
          </div>
          <div className="flex items-center justify-between">
            <dt className="text-slate-400">Private IP</dt>
            <dd className="font-mono text-xs">{server.ipAddress ?? "—"}</dd>
          </div>
        </dl>
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Live stats</h2>
        {live ? (
          <div className="space-y-4 text-sm">
            <div>
              <div className="mb-1.5 flex justify-between">
                <span className="text-slate-400">CPU</span>
                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
              </div>
              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
            </div>
            <div>
              <div className="mb-1.5 flex justify-between">
                <span className="text-slate-400">Memory</span>
                <span className="font-semibold">
                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
                </span>
              </div>
              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">Uptime</span>
              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">Network I/O</span>
              <span className="font-mono text-xs">
                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
              </span>
            </div>
          </div>
        ) : (
          <p className="text-sm text-slate-400">
            {pveUnavailable
              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
              : "Live stats appear once the server is provisioned."}
          </p>
        )}
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Configuration</h2>
        <dl className="space-y-2.5 text-sm">
          <div className="flex justify-between">
            <dt className="text-slate-400">Plan</dt>
            <dd>
              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
              {server.plan.diskGB} GB NVMe
            </dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">Bandwidth</dt>
            <dd>{server.plan.bandwidthTB} TB / month</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">Operating system</dt>
            <dd>{server.osTemplate.name}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">Created</dt>
            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
            <dd>
              {server.isFree
                ? "Free — never expires"
                : server.expiresAt
                  ? server.expiresAt.toISOString().slice(0, 10)
                  : "—"}
            </dd>
          </div>
        </dl>
      </div>

      {!server.isFree ? (
        <RenewalCard
          serverId={server.id}
          autoRenew={server.autoRenew}
          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
          priceCents={server.plan.priceCents}
          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
        />
      ) : (
        <div className="card">
          <h2 className="mb-3 font-semibold">Subscription</h2>
          <p className="text-sm text-slate-400">
            This server is free of charge — no billing, no expiry.
          </p>
        </div>
      )}

      <div className="card md:col-span-2">
        <h2 className="mb-3 font-semibold">Project</h2>
        <ProjectAssign
          serverId={server.id}
          currentProjectId={server.projectId}
          projects={projects.map((p) => ({ id: p.id, name: p.name, color: p.color }))}
        />
      </div>
    </div>
  );

  /* ---------- Tab: Snapshots ---------- */
  const snapshotsTab = (
    <div className="space-y-6">
      <div className="card">
        <h2 className="mb-4 font-semibold">Create snapshot</h2>
        <CreateSnapshotForm serverId={server.id} disabled={busy || !steady} />
      </div>
      <div className="card p-0">
        <p className="section-label px-4 pt-4">Snapshots</p>
        {pveUnavailable && snapshots.length === 0 ? (
          <p className="px-4 py-6 text-sm text-amber-300">
            Could not load snapshots — the hypervisor is briefly unavailable. Try again in a moment.
          </p>
        ) : snapshots.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            No snapshots yet. Take one before risky changes so you can roll back instantly.
          </p>
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th>Taken</th>
                <th>Description</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {snapshots.map((s) => (
                <tr key={s.name}>
                  <td className="font-mono text-xs">{s.name}</td>
                  <td className="text-slate-400">
                    {s.snaptime ? new Date(s.snaptime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
                  </td>
                  <td className="text-slate-400">{s.description || "—"}</td>
                  <td>
                    <SnapshotActions serverId={server.id} name={s.name} disabled={busy || !steady} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
      <p className="text-xs text-slate-500">
        Snapshots live on the same storage as your server — use backups for disaster recovery.
      </p>
    </div>
  );

  /* ---------- Tab: Backups ---------- */
  const backupsTab = (
    <div className="space-y-6">
      <div className="card flex flex-wrap items-center justify-between gap-4">
        <div>
          <h2 className="font-semibold">Backups</h2>
          <p className="mt-1 text-sm text-slate-400">
            Full-image backups stored on a separate 4 TB pool, independent from your server&apos;s NVMe storage.
          </p>
        </div>
        <CreateBackupButton serverId={server.id} disabled={busy || !steady} />
      </div>
      <div className="card p-0">
        {pveUnavailable && backups.length === 0 ? (
          <p className="px-4 py-6 text-sm text-amber-300">
            Could not load backups — the hypervisor is briefly unavailable. Try again in a moment.
          </p>
        ) : backups.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            No backups yet. Create one now — restores are handled by support within minutes.
          </p>
        ) : (
          <table className="table-shell">
            <thead>
              <tr>
                <th>Backup</th>
                <th>Created</th>
                <th className="text-right">Size</th>
              </tr>
            </thead>
            <tbody>
              {backups.map((b) => (
                <tr key={b.volid}>
                  <td className="font-mono text-xs">{b.volid.split("/").pop()}</td>
                  <td className="text-slate-400">
                    {b.ctime ? new Date(b.ctime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
                  </td>
                  <td className="text-right text-slate-400">{fmtBytes(b.size ?? 0)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
      <p className="text-xs text-slate-500">
        Need a restore? Open a support ticket with the backup name and we&apos;ll handle it.
      </p>
    </div>
  );

  /* ---------- Tab: Networking ---------- */
  const networking = (
    <div className="space-y-6">
      <div className="glass p-4 text-sm text-slate-300">
        Your server sits behind NAT on a private network ({server.ipAddress ?? "10.20.0.x"}). Public
        ports on <span className="font-mono text-brand-300">{publicIp}</span> are forwarded to ports
        inside your VM — connect to{" "}
        <span className="font-mono text-brand-300">{publicIp}:&lt;public port&gt;</span> to reach a
        forwarded service.
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Port forwards</p>
        <table className="table-shell mt-2">
          <thead>
            <tr>
              <th>Public endpoint</th>
              <th>Guest port</th>
              <th>Protocol</th>
              <th className="text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td className="font-mono text-xs">
                {server.sshPort ? `${publicIp}:${server.sshPort}` : "—"}
              </td>
              <td className="font-mono text-xs">22</td>
              <td className="text-slate-400">tcp</td>
              <td className="text-right">
                <Badge tone="slate">SSH — managed</Badge>
              </td>
            </tr>
            {server.portForwards.map((f) => (
              <tr key={f.id}>
                <td className="font-mono text-xs">
                  {publicIp}:{f.publicPort}
                </td>
                <td className="font-mono text-xs">{f.guestPort}</td>
                <td className="text-slate-400">{f.protocol}</td>
                <td className="text-right">
                  <DeleteForwardButton serverId={server.id} forwardId={f.id} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {server.portForwards.length === 0 && (
          <p className="px-4 pb-4 text-sm text-slate-500">
            No custom forwards yet — add one below to expose a web server, game server, or any other
            service.
          </p>
        )}
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Add port forward</h2>
        <AddForwardForm serverId={server.id} />
        <p className="mt-3 text-xs text-slate-500">
          A free public port (20000–29999) is assigned automatically. Up to 10 forwards per server.
        </p>
      </div>
    </div>
  );

  /* ---------- Tab: Resize ---------- */
  const resize = (
    <div className="space-y-6">
      <ResizePicker
        serverId={server.id}
        currentPlanId={server.planId}
        currentDiskGB={server.plan.diskGB}
        plans={activePlans.map((p) => ({
          id: p.id,
          name: p.name,
          cpuCores: p.cpuCores,
          ramMB: p.ramMB,
          diskGB: p.diskGB,
          bandwidthTB: p.bandwidthTB,
          priceCents: p.priceCents,
        }))}
        disabled={busy || !steady}
      />
    </div>
  );

  /* ---------- Tab: Activity ---------- */
  const activity = (
    <div className="card p-0">
      <p className="section-label px-4 pt-4">Server jobs</p>
      {server.jobs.length === 0 ? (
        <p className="px-4 py-6 text-sm text-slate-400">No jobs recorded for this server yet.</p>
      ) : (
        <table className="table-shell mt-2">
          <thead>
            <tr>
              <th>Job</th>
              <th>Status</th>
              <th>Attempts</th>
              <th>Detail</th>
              <th className="text-right">Created</th>
            </tr>
          </thead>
          <tbody>
            {server.jobs.map((j) => (
              <tr key={j.id}>
                <td className="font-medium">{j.type.toLowerCase().replace(/_/g, " ")}</td>
                <td>
                  <StatusDot status={j.status} />
                </td>
                <td className="text-slate-400">{j.attempts}</td>
                <td className="max-w-64 truncate text-xs text-red-400">
                  {j.status === "FAILED" ? j.error ?? "unknown error" : ""}
                </td>
                <td className="text-right text-slate-400">{timeAgo(j.createdAt)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );

  return (
    <div>
      {busy && <AutoRefresh />}

      <div className="mb-6 flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="flex flex-wrap items-center gap-3">
            <h1 className="page-title">{server.hostname}</h1>
            <StatusDot status={server.status} />
          </div>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <Badge tone="slate">{server.plan.name}</Badge>
            <Badge tone="slate">{server.osTemplate.name}</Badge>
            {server.isFree && <Badge tone="brand">free</Badge>}
            {!server.isFree && (
              <Badge tone="slate">{fmtMoney(server.plan.priceCents)}/mo</Badge>
            )}
          </div>
        </div>
        {server.status !== "SUSPENDED" && !transitional && (
          <ServerControls serverId={server.id} status={server.status} busy={busy} />
        )}
      </div>

      {server.status === "SUSPENDED" && (
        <div className="card mb-6 border-red-500/30 text-sm text-red-300">
          This server has been suspended{server.suspendedNote ? `: ${server.suspendedNote}` : "."}{" "}
          Contact support if you believe this is a mistake.
        </div>
      )}

      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          {server.status === "DELETING"
            ? "Your server is being deleted…"
            : "Your server is being set up — this usually takes under two minutes. The page refreshes automatically."}
        </div>
      )}

      <ServerTabs
        initialTab={tab}
        overview={overview}
        metrics={<MetricsPanel serverId={server.id} />}
        snapshots={snapshotsTab}
        backups={backupsTab}
        networking={networking}
        resize={resize}
        activity={activity}
      />
    </div>
  );
}

