import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { priceForDomain, namecheapConfigured } from "@/lib/namecheap";
import { PageHeader, EmptyState, fmtMoney } from "@/components/ui/primitives";
import { RegisterDomainForm } from "@/components/customer/RegisterDomainForm";

export const dynamic = "force-dynamic";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;

export default async function RegisterDomainPage({
  searchParams,
}: {
  searchParams: Promise<{ domain?: string }>;
}) {
  const user = await requireUser();
  const { domain: raw } = await searchParams;
  const domain = (raw ?? "").toLowerCase().trim();
  const valid = DOMAIN_RE.test(domain);
  const priceCents = valid ? priceForDomain(domain) : null;

  if (!valid || priceCents === null || !namecheapConfigured()) {
    return (
      <div className="space-y-6">
        <PageHeader title="Register domain" />
        <EmptyState
          title={
            !namecheapConfigured()
              ? "Domain registration is not available yet"
              : !valid
                ? "No domain selected"
                : "This TLD is not supported"
          }
          sub={
            !namecheapConfigured()
              ? "Registration activates once the Namecheap integration is configured."
              : "Search for an available domain first, then continue to registration from the results."
          }
          action={
            <Link href="/dashboard/domains" className="btn-primary">
              Back to domain search
            </Link>
          }
        />
      </div>
    );
  }

  const afterCents = user.balanceCents - priceCents;

  return (
    <div className="space-y-6">
      <PageHeader title="Register domain" sub="Complete registrant details to finish registration." />

      <div className="grid gap-6 lg:grid-cols-[1fr_340px]">
        <div className="card">
          <RegisterDomainForm domain={domain} defaultEmail={user.email} />
        </div>

        <div className="space-y-6">
          <div className="card">
            <p className="section-label mb-3">Order summary</p>
            <dl className="space-y-3 text-sm">
              <div className="flex justify-between">
                <dt className="text-slate-400">Domain</dt>
                <dd className="font-mono">{domain}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-400">Term</dt>
                <dd>1 year</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-400">WHOIS privacy</dt>
                <dd className="text-emerald-400">Included</dd>
              </div>
              <div className="divider" />
              <div className="flex justify-between text-base font-semibold">
                <dt>Due today</dt>
                <dd>{fmtMoney(priceCents)}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-400">Wallet balance</dt>
                <dd>{fmtMoney(user.balanceCents)}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-400">Balance after</dt>
                <dd className={afterCents < 0 ? "font-semibold text-red-400" : "text-emerald-400"}>
                  {fmtMoney(afterCents)}
                </dd>
              </div>
            </dl>
            {afterCents < 0 && (
              <div className="mt-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
                Insufficient balance.{" "}
                <Link href="/dashboard/billing" className="font-semibold underline">
                  Add funds
                </Link>{" "}
                before registering.
              </div>
            )}
          </div>
          <p className="text-xs text-slate-500">
            The fee is charged from your wallet. If registration fails for any reason you are
            refunded automatically.
          </p>
        </div>
      </div>
    </div>
  );
}

import { notFound } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { getDnsHosts, namecheapConfigured, type DnsHost } from "@/lib/namecheap";
import { PageHeader, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import {
  DomainAutoRenewToggle,
  RenewDomainButton,
  PointAtServerButton,
  DnsAddForm,
  DnsDeleteButton,
} from "@/components/customer/DomainControls";

export const dynamic = "force-dynamic";

export default async function DomainPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await requireUser();
  const domain = await db.domain.findUnique({ where: { id } });
  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) notFound();

  const publicIp = process.env.PUBLIC_IP ?? "";

  let dnsHosts: DnsHost[] | null = null;
  let dnsError: string | null = null;
  if (domain.status === "ACTIVE" && namecheapConfigured()) {
    try {
      dnsHosts = await getDnsHosts(domain.name);
    } catch (e) {
      dnsError = String(e instanceof Error ? e.message : e).slice(0, 200);
    }
  }

  const statusDot =
    domain.status === "ACTIVE" ? "RUNNING" : domain.status === "PENDING" ? "PENDING" : "ERROR";

  return (
    <div className="space-y-6">
      {domain.status === "PENDING" && <AutoRefresh />}
      <PageHeader title={domain.name} sub="Domain management">
        <Link href="/dashboard/domains" className="btn-ghost">
          ← All domains
        </Link>
      </PageHeader>

      {domain.status === "FAILED" && (
        <div className="card border-red-500/30 text-sm text-red-300">
          Registration failed{domain.error ? `: ${domain.error}` : "."} You were refunded — try
          again or contact support.
        </div>
      )}

      <div className="grid gap-6 md:grid-cols-2">
        <div className="card">
          <h2 className="mb-4 font-semibold">Registration</h2>
          <dl className="space-y-3 text-sm">
            <div className="flex items-center justify-between">
              <dt className="text-slate-400">Status</dt>
              <dd>
                <StatusDot status={statusDot} label={domain.status} />
              </dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Registered</dt>
              <dd>{domain.registeredAt ? domain.registeredAt.toISOString().slice(0, 10) : "—"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Expires</dt>
              <dd>{domain.expiresAt ? domain.expiresAt.toISOString().slice(0, 10) : "—"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Renewal price</dt>
              <dd>{fmtMoney(domain.priceCents)}/yr</dd>
            </div>
            <div className="flex items-center justify-between">
              <dt className="text-slate-400">Auto-renew</dt>
              <dd>
                <DomainAutoRenewToggle domainId={domain.id} autoRenew={domain.autoRenew} />
              </dd>
            </div>
          </dl>
          {domain.status === "ACTIVE" && (
            <div className="mt-5">
              <RenewDomainButton domainId={domain.id} priceCents={domain.priceCents} />
            </div>
          )}
        </div>

        <div className="card">
          <h2 className="mb-3 font-semibold">Point at my server</h2>
          <p className="text-sm text-slate-400">
            One click sets <span className="font-mono text-brand-300">@</span> and{" "}
            <span className="font-mono text-brand-300">www</span> A records to your public server IP{" "}
            <span className="font-mono text-brand-300">{publicIp}</span>. Add a port forward for
            your web server (port 80/443) on the server&apos;s Networking tab to serve traffic.
          </p>
          <div className="mt-4">
            {domain.status === "ACTIVE" ? (
              <PointAtServerButton domainId={domain.id} ip={publicIp} />
            ) : (
              <Badge tone="slate">available once the domain is active</Badge>
            )}
          </div>
        </div>
      </div>

      <div className="card p-0">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">DNS records</p>
          <Badge tone="slate">Namecheap DNS</Badge>
        </div>
        {domain.status !== "ACTIVE" ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            DNS management becomes available once the domain is active.
          </p>
        ) : dnsError ? (
          <div className="px-4 py-6">
            <p className="text-sm text-amber-300">Could not load DNS records: {dnsError}</p>
            <p className="mt-1 text-xs text-slate-500">
              The registrar API may be briefly unavailable — refresh to retry.
            </p>
          </div>
        ) : dnsHosts && dnsHosts.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            No records yet — add your first record below.
          </p>
        ) : dnsHosts ? (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th>Type</th>
                <th>Value</th>
                <th>TTL</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {dnsHosts.map((h, i) => (
                <tr key={`${h.type}-${h.name}-${i}`}>
                  <td className="font-mono text-xs">{h.name}</td>
                  <td>
                    <Badge tone="slate">{h.type}</Badge>
                    {h.type === "MX" && h.mxPref !== undefined && (
                      <span className="ml-1.5 text-xs text-slate-500">prio {h.mxPref}</span>
                    )}
                  </td>
                  <td className="max-w-72 truncate font-mono text-xs text-slate-300">{h.address}</td>
                  <td className="text-slate-400">{h.ttl}</td>
                  <td className="text-right">
                    <DnsDeleteButton
                      domainId={domain.id}
                      record={{ name: h.name, type: h.type, address: h.address }}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p className="px-4 py-6 text-sm text-slate-400">DNS is unavailable.</p>
        )}
      </div>

      {domain.status === "ACTIVE" && !dnsError && (
        <div className="card">
          <h2 className="mb-4 font-semibold">Add DNS record</h2>
          <DnsAddForm domainId={domain.id} />
        </div>
      )}
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { AddFunds } from "@/components/customer/AddFunds";

export const dynamic = "force-dynamic";

export default async function BillingPage({
  searchParams,
}: {
  searchParams: Promise<{ paid?: string; canceled?: string }>;
}) {
  const { paid, canceled } = await searchParams;
  const user = await requireUser();
  const [transactions, paidServers] = await Promise.all([
    db.walletTransaction.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 60,
    }),
    db.server.findMany({
      where: { userId: user.id, isFree: false, status: { not: "DELETING" } },
      include: { plan: true },
      orderBy: { expiresAt: "asc" },
    }),
  ]);

  const monthlySpendCents = paidServers.reduce((sum, s) => sum + s.plan.priceCents, 0);
  const upcoming = paidServers.filter((s) => s.expiresAt !== null);

  return (
    <div className="space-y-6">
      <PageHeader title="Billing" sub="Wallet, renewals and transaction history." />

      {paid === "1" && (
        <div className="card border-emerald-500/30 bg-emerald-500/[0.06] text-sm text-emerald-300">
          Payment received — your balance updates within seconds. Refresh if you don&apos;t see it
          yet.
        </div>
      )}
      {canceled === "1" && (
        <div className="card border-amber-500/30 bg-amber-500/[0.06] text-sm text-amber-300">
          Checkout canceled — no charge was made.
        </div>
      )}

      <div className="card relative overflow-hidden">
        <div
          className="pointer-events-none absolute inset-0"
          style={{
            background:
              "linear-gradient(120deg, rgb(59 130 246 / 0.12), rgb(111 71 245 / 0.14) 55%, transparent)",
          }}
        />
        <div className="relative flex flex-wrap items-end justify-between gap-6">
          <div>
            <p className="text-sm text-slate-400">Wallet balance</p>
            <p className="mt-1 text-4xl font-bold tracking-tight">
              <span className="grad-text">{fmtMoney(user.balanceCents)}</span>
            </p>
            <p className="mt-2 text-xs text-slate-500">
              Servers renew and domains register straight from this balance.
            </p>
          </div>
          <AddFunds />
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-[340px_1fr]">
        <div className="space-y-6">
          <div className="card">
            <p className="section-label mb-3">Monthly spend</p>
            <p className="text-2xl font-bold">{fmtMoney(monthlySpendCents)}<span className="text-sm font-normal text-slate-400">/mo</span></p>
            <p className="mt-1 text-xs text-slate-500">
              {paidServers.length} paid server{paidServers.length === 1 ? "" : "s"} across your
              account.
            </p>
          </div>

          <div className="card">
            <p className="section-label mb-3">Upcoming renewals</p>
            {upcoming.length === 0 ? (
              <p className="text-sm text-slate-400">No renewals scheduled.</p>
            ) : (
              <ul className="space-y-3">
                {upcoming.map((s) => (
                  <li key={s.id} className="flex items-center justify-between gap-3 text-sm">
                    <Link
                      href={`/dashboard/servers/${s.id}`}
                      className="min-w-0 flex-1 truncate font-medium hover:text-brand-300"
                    >
                      {s.hostname}
                    </Link>
                    <span className="shrink-0 text-xs text-slate-400">
                      {s.expiresAt!.toISOString().slice(0, 10)}
                    </span>
                    <span className="shrink-0 font-mono text-xs text-slate-300">
                      {fmtMoney(s.plan.priceCents)}
                    </span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>

        <div className="card overflow-x-auto p-0">
          <p className="section-label px-4 pt-4">Transactions</p>
          {transactions.length === 0 ? (
            <p className="px-4 py-8 text-sm text-slate-400">
              No transactions yet — your invoices and top-ups will appear here.
            </p>
          ) : (
            <table className="table-shell mt-2 min-w-[520px]">
              <thead>
                <tr>
                  <th>Description</th>
                  <th className="text-right">Amount</th>
                  <th className="text-right">Date</th>
                </tr>
              </thead>
              <tbody>
                {transactions.map((t) => (
                  <tr key={t.id}>
                    <td>{t.description}</td>
                    <td
                      className={`text-right font-mono ${
                        t.amountCents < 0 ? "text-red-400" : "text-emerald-400"
                      }`}
                    >
                      {t.amountCents < 0 ? "−" : "+"}
                      {fmtMoney(Math.abs(t.amountCents))}
                    </td>
                    <td className="text-right text-slate-400" title={t.createdAt.toISOString()}>
                      {timeAgo(t.createdAt)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}

