import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, ComingSoon, timeAgo } from "@/components/ui/primitives";
import {
  ProfileForm,
  PasswordForm,
  AddSshKeyForm,
  DeleteSshKeyButton,
} from "@/components/customer/SettingsForms";

export const dynamic = "force-dynamic";

function shortKey(publicKey: string): string {
  const parts = publicKey.trim().split(/\s+/);
  const body = parts[1] ?? parts[0] ?? "";
  const type = parts[0] ?? "";
  if (body.length <= 40) return publicKey;
  return `${type} ${body.slice(0, 24)}…${body.slice(-12)}`;
}

export default async function SettingsPage() {
  const user = await requireUser();
  const sshKeys = await db.sshKey.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });

  return (
    <div className="space-y-6">
      <PageHeader title="Settings" sub="Profile, security and access credentials." />

      <div className="card">
        <h2 className="mb-4 font-semibold">Profile</h2>
        <ProfileForm name={user.name} email={user.email} />
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Password</h2>
        <PasswordForm />
      </div>

      <div className="card">
        <div className="mb-1 flex items-center justify-between">
          <h2 className="font-semibold">SSH keys</h2>
          <span className="text-xs text-slate-500">
            {sshKeys.length} key{sshKeys.length === 1 ? "" : "s"}
          </span>
        </div>
        <p className="mb-5 text-sm text-slate-400">
          Keys are injected into new servers automatically at deploy time.
        </p>

        {sshKeys.length > 0 && (
          <ul className="mb-6 divide-y divide-white/[0.05] rounded-xl border border-white/[0.06]">
            {sshKeys.map((k) => (
              <li key={k.id} className="flex items-center justify-between gap-4 px-4 py-3">
                <div className="min-w-0">
                  <p className="text-sm font-medium">{k.name}</p>
                  <p className="truncate font-mono text-xs text-slate-500">{shortKey(k.publicKey)}</p>
                </div>
                <div className="flex shrink-0 items-center gap-3">
                  <span className="hidden text-xs text-slate-500 sm:block">
                    added {timeAgo(k.createdAt)}
                  </span>
                  <DeleteSshKeyButton keyId={k.id} />
                </div>
              </li>
            ))}
          </ul>
        )}

        <AddSshKeyForm />
      </div>

      <ComingSoon
        feature="API access"
        note="Programmatic tokens for deploying and managing servers via REST are on the roadmap."
      />
    </div>
  );
}
